  function start(){if(editing)return;window.spcEditSession?.begin();editing=true;document.body.classList.add('quality-page-editor-open');entry.hidden=true;bar=document.createElement('section');bar.className='quality-editor-bar';bar.innerHTML='<b>编辑分析页面</b><span>　点击图表进行配置</span><div class="quality-editor-bar-actions"><button type="button" data-add>添加组件</button><button type="button" data-reset>恢复默认</button><button type="button" data-preview>页面预览</button><button type="button" class="primary" data-finish>完成编辑</button></div>';const main=q(document,'main');(document.querySelector('.top-actions')||main)?.append(bar);q(bar,'[data-add]').onclick=addComponent;q(bar,'[data-reset]').onclick=restoreDefault;q(bar,'[data-preview]').onclick=()=>{const on=document.body.classList.toggle('quality-page-preview');q(bar,'[data-preview]').textContent=on?'返回编辑':'页面预览';if(on){drawer?.remove();drawer=null}else if(selected>=0)renderDrawer()};q(bar,'[data-finish]').onclick=finish;window.syncEditorHeader?.();select(0)}
